/// The descriptor of a machine opcode the matcher tables emit.
pub fn desc(opcode: u16) -> Option<&'static InstrDesc> {
    INSTRS.binary_search_by_key(&opcode, |&(o, _)| o).ok().map(|at| &INSTRS[at].1)
}

/// `(mayLoad, mayStore)` of a machine opcode.
pub fn memory_flags(opcode: u16) -> (bool, bool) {
    desc(opcode).map_or((false, false), |d| (d.may_load(), d.may_store()))
}
